SELECT public.save_customer('{"display_name":"Frozen name","vat_applicable":true}','94000000-0000-4000-8000-000000000002',NULL);
SELECT extensions.lives_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000003',NULL,'{"client_name":"Preview","client_phone":"","activity_date":"2026-10-01","num_participants":1}','94000000-0000-4000-8000-000000000002',0)$$,'atomic create and link');
SELECT extensions.lives_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000003',NULL,'{"client_name":"Preview","client_phone":"","activity_date":"2026-10-01","num_participants":1}','94000000-0000-4000-8000-000000000002',0)$$,'same request replay succeeds');
SELECT extensions.is((SELECT count(*) FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'),1::bigint,'no duplicate order');
SELECT extensions.is((SELECT count(*) FROM public.customer_snapshots WHERE customer_id='94000000-0000-4000-8000-000000000002'),1::bigint,'no duplicate snapshot');
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000003',NULL,'{"client_name":"Changed"}',NULL,0)$$,'40001','order_save_request_conflict','changed replay rejected');
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000004',NULL,'{"client_name":"Rollback","client_phone":"","activity_date":"2026-10-01","num_participants":1}','94000000-0000-4000-8000-000000000099',0)$$,'P0001','active_customer_required','invalid link fails');
SELECT extensions.is((SELECT count(*) FROM public.orders WHERE client_name='Rollback'),0::bigint,'failed link rolls back insert');
SELECT public.save_customer('{"display_name":"Master changed","vat_applicable":false}','94000000-0000-4000-8000-000000000002',1);
SELECT extensions.lives_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000005',id,'{"notes":"Edit only"}',NULL,1) FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'$$,'normal edit preserves snapshot');
SELECT extensions.is((SELECT client_name FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'),'Frozen name','master changes do not overwrite history');
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000006',NULL,'{"id":"94000000-0000-4000-8000-000000000099"}',NULL,0)$$,'22023','invalid_order_fields','unapproved column rejected');
SELECT extensions.lives_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000007',NULL,'{"client_name":"Legacy","client_phone":"","activity_date":"2026-10-01","num_participants":1}',NULL,0)$$,'legacy order without customer remains supported');
SELECT extensions.is((SELECT customer_snapshot_id FROM public.orders WHERE client_name='Legacy'),NULL::uuid,'legacy create has no artificial snapshot');
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000008',id,'{"client_email":""}',NULL,1) FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'$$,'42501','customer_snapshot_immutable','normalized null snapshot fields cannot be overwritten');
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000009',id,'{"num_participants":null}','94000000-0000-4000-8000-000000000002',1) FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'$$,'23502',NULL,'invalid operational edit rolls back new customer snapshot');
SELECT extensions.is((SELECT count(*) FROM public.customer_snapshots WHERE customer_id='94000000-0000-4000-8000-000000000002'),1::bigint,'failed edit retains only original snapshot');
SELECT extensions.lives_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000010',id,'{"notes":"Reviewed"}','94000000-0000-4000-8000-000000000002',1) FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'$$,'explicit refresh links latest customer with normal edit');
SELECT extensions.is((SELECT customer_record_version FROM public.orders WHERE customer_id='94000000-0000-4000-8000-000000000002'),2,'explicit refresh appends a revision');
UPDATE public.orders SET payment_status=U&'\05DE\05D6\05D5\05DE\05DF' WHERE client_name='Legacy';
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000011',id,jsonb_build_object('payment_status',U&'\05DC\05D0 \05E9\05D5\05DC\05DD'),'94000000-0000-4000-8000-000000000002',0) FROM public.orders WHERE client_name='Legacy'$$,'P0001','unpaid_order_required','eligibility checked before incoming payment status change');
