INSERT INTO auth.users(id,email) VALUES ('94000000-0000-4000-8000-000000000012','order-form-instructor@example.test');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"94000000-0000-4000-8000-000000000012"}',true);
SET LOCAL ROLE authenticated;
SELECT extensions.throws_ok($$SELECT public.save_order_form('94000000-0000-4000-8000-000000000013',NULL,'{"notes":"Denied"}',NULL,0)$$,'42501','order_access_denied','instructor cannot create orders');
